621. /**
622.  * Helper to load the OpenCode SDK ESM module
623.  *
624.  * Uses a two-phase approach:
625.  * 1. Try simple dynamic import - works when SDK is in same node_modules tree
626.  * 2. Fall back to smart ESM resolution for edge cases (pnpm, global installs, monorepos)
627.  */
628. async function loadOpenCodeSDK(): Promise<LoadedOpenCodeSDKModule> {
629.   const directImports = [
630.     { specifier: '@opencode-ai/sdk/v2', exportPath: './v2' as const, apiVersion: 'v2' as const },
631.     { specifier: '@opencode-ai/sdk', exportPath: '.' as const, apiVersion: 'v1' as const },
632.   ];
633. 
634.   for (const candidate of directImports) {
635.     try {
636.       logger.debug(`Attempting dynamic import of ${candidate.specifier}`);
637.       const module = (await import(candidate.specifier)) as unknown as OpenCodeSDKModule;
638.       return { ...module, apiVersion: candidate.apiVersion };
639.     } catch (error) {
640.       logger.debug(`Dynamic import failed for ${candidate.specifier}`, { error });
641.     }
642.   }
643. 
644.   const basePath =
645.     cliState.basePath && path.isAbsolute(cliState.basePath) ? cliState.basePath : process.cwd();
646. 
647.   for (const candidate of directImports) {
648.     try {
649.       const modulePath = resolveEsmPackage('@opencode-ai/sdk', candidate.exportPath, basePath);
650.       logger.debug(`Resolved OpenCode SDK path (${candidate.apiVersion}): ${modulePath}`);
651.       const module = (await importModule(modulePath)) as OpenCodeSDKModule;
652.       return { ...module, apiVersion: candidate.apiVersion };
653.     } catch (error) {
654.       logger.debug(`Smart resolution failed for ${candidate.specifier}`, { error });
655.     }
656.   }
657. 
658.   const err = new Error('Failed to resolve @opencode-ai/sdk');
659.   logger.error(`Failed to load OpenCode SDK: ${err}`);
660.   throw new Error(
661.     dedent`The @opencode-ai/sdk package is required but not installed.
662. 
663.     To use the OpenCode SDK provider, install it with:
664.       npm install @opencode-ai/sdk
665. 
666.     For more information, see: https://www.promptfoo.dev/docs/providers/opencode-sdk/`,
667.   );
668. }
