1. import launch from "cross-spawn";
2. import { stop, bindAbort } from "../process.js";
3. export async function createOpencodeServer(options) {
4.     options = Object.assign({
5.         hostname: "127.0.0.1",
6.         port: 4096,
7.         timeout: 5000,
8.     }, options ?? {});
9.     const args = [`serve`, `--hostname=${options.hostname}`, `--port=${options.port}`];
10.     if (options.config?.logLevel)
11.         args.push(`--log-level=${options.config.logLevel}`);
12.     const proc = launch(`opencode`, args, {
13.         env: {
14.             ...process.env,
15.             OPENCODE_CONFIG_CONTENT: JSON.stringify(options.config ?? {}),
16.         },
17.     });
18.     let clear = () => { };
19.     const url = await new Promise((resolve, reject) => {
20.         const id = setTimeout(() => {
21.             clear();
22.             stop(proc);
23.             reject(new Error(`Timeout waiting for server to start after ${options.timeout}ms`));
24.         }, options.timeout);
25.         let output = "";
26.         let resolved = false;
27.         proc.stdout?.on("data", (chunk) => {
28.             if (resolved)
29.                 return;
30.             output += chunk.toString();
31.             const lines = output.split("\n");
32.             for (const line of lines) {
33.                 if (line.startsWith("opencode server listening")) {
34.                     const match = line.match(/on\s+(https?:\/\/[^\s]+)/);
35.                     if (!match) {
36.                         clear();
37.                         stop(proc);
38.                         clearTimeout(id);
39.                         reject(new Error(`Failed to parse server url from output: ${line}`));
40.                         return;
41.                     }
42.                     clearTimeout(id);
43.                     resolved = true;
44.                     resolve(match[1]);
45.                     return;
46.                 }
47.             }
48.         });
49.         proc.stderr?.on("data", (chunk) => {
50.             output += chunk.toString();
51.         });
52.         proc.on("exit", (code) => {
53.             clearTimeout(id);
54.             let msg = `Server exited with code ${code}`;
55.             if (output.trim()) {
56.                 msg += `\nServer output: ${output}`;
57.             }
58.             reject(new Error(msg));
59.         });
60.         proc.on("error", (error) => {
61.             clearTimeout(id);
62.             reject(error);
63.         });
64.         clear = bindAbort(proc, options.signal, () => {
65.             clearTimeout(id);
66.             reject(options.signal?.reason);
67.         });
68.     });
69.     return {
70.         url,
71.         close() {
72.             clear();
73.             stop(proc);
74.         },
75.     };
76. }
77. export function createOpencodeTui(options) {
78.     const args = [];
79.     if (options?.project) {
80.         args.push(`--project=${options.project}`);
81.     }
82.     if (options?.model) {
83.         args.push(`--model=${options.model}`);
84.     }
85.     if (options?.session) {
86.         args.push(`--session=${options.session}`);
87.     }
88.     if (options?.agent) {
89.         args.push(`--agent=${options.agent}`);
90.     }
91.     const proc = launch(`opencode`, args, {
92.         stdio: "inherit",
93.         env: {
94.             ...process.env,
95.             OPENCODE_CONFIG_CONTENT: JSON.stringify(options?.config ?? {}),
96.         },
97.     });
98.     const clear = bindAbort(proc, options?.signal);
99.     return {
100.         close() {
101.             clear();
102.             stop(proc);
103.         },
104.     };
105. }
